        public final String path;public final long size;public final Opener opener;public boolean directory;
        public Source(String path,long size,Opener opener){this.path=safePath(path);if(size<0)throw new IllegalArgumentException("文件长度未知");this.size=size;this.opener=opener;}
        public static Source directory(String path){Source source=new Source(path,0,()->new ByteArrayInputStream(new byte[0]));source.directory=true;return source;}
